import java.nio.file.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
record Outcome(String file,boolean ok,int score,String reason){}
public class ResultProcessor{
 static Path dir=Path.of("data/scores");
 static void makeFiles(int n)throws IOException{Files.createDirectories(dir);for(int i=1;i<=n;i++){Path p=dir.resolve(String.format("score-%05d.txt",i));if(i%17==0)continue;if(i%19==0)Files.writeString(p,"BROKEN");else Files.writeString(p,"student=S"+i+"\nscore="+(i%101));}}
 static Outcome process(Path p){try{List<String>l=Files.readAllLines(p);if(l.size()<2||!l.get(1).startsWith("score="))throw new IllegalArgumentException("Corrupt file");int score=Integer.parseInt(l.get(1).substring(6));return new Outcome(p.getFileName().toString(),true,score,"OK");}catch(Exception e){return new Outcome(p.getFileName().toString(),false,0,e.getClass().getSimpleName()+": "+e.getMessage());}}
 static void run(int pool,List<Path>paths)throws Exception{ExecutorService ex=Executors.newFixedThreadPool(pool);ConcurrentHashMap<String,Outcome>map=new ConcurrentHashMap<>();List<Future<Outcome>>f=new ArrayList<>();long start=System.nanoTime();try{for(Path p:paths)f.add(ex.submit(()->process(p)));for(Future<Outcome>v:f){try{Outcome o=v.get();map.put(o.file(),o);}catch(ExecutionException e){map.put("unexpected"+map.size(),new Outcome("unexpected",false,0,e.toString()));}}}finally{ex.shutdown();if(!ex.awaitTermination(30,TimeUnit.SECONDS))ex.shutdownNow();}long ok=map.values().stream().filter(Outcome::ok).count(),bad=map.size()-ok;int total=map.values().stream().filter(Outcome::ok).mapToInt(Outcome::score).sum();System.out.printf("pool=%d submitted=%d success=%d failed=%d scoreTotal=%d elapsed_ms=%.3f%n",pool,f.size(),ok,bad,total,(System.nanoTime()-start)/1e6);}
 public static void main(String[]a)throws Exception{int n=a.length>0?Integer.parseInt(a[0]):200;makeFiles(n);List<Path>p=new ArrayList<>();for(int i=1;i<=n;i++)p.add(dir.resolve(String.format("score-%05d.txt",i)));System.out.println("Missing every 17th; corrupt every 19th.");for(int k:new int[]{1,2,4,8})run(k,p);System.out.println("One file failure is isolated; all submitted tasks are collected.");}}
